(()=>{const dialog=document.querySelector('.image-dialog');if(!dialog)return;let opener;document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{opener=b;const image=dialog.querySelector('img');image.src=b.dataset.image;image.alt=b.querySelector('img').alt;dialog.querySelector('a').href=b.dataset.image;dialog.showModal()}));dialog.querySelector('.image-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})})();
